        ("row", lambda r, c: r),
        ("col", lambda r, c: c),
        ("diag", lambda r, c: c-r),
        ("anti", lambda r, c: r+c),
    ]
    candidates = []
    for name, coord in forms:
        lines = {}
        valid = True
        for r, c, color in points:
            k = coord(r, c)
            if k in lines and lines[k][0] != color:
                valid = False
                break
            if k not in lines:
                lines[k] = [color, 0]
            lines[k][1] += 1
        if not valid:
