        lo, hi = min(lines), max(lines)
        period = None
        for p in range(1, hi-lo+2):
            residues = {}
            for k, (color, _) in lines.items():
                phase = k % p
                if phase in residues and residues[phase] != color:
                    break
                residues[phase] = color
            else:
                period = p
                break
        if period is None:
